const userProviders = `-- name: UserProviders :many
SELECT provider FROM auth_identities WHERE user_id = $1
`

// Which sign-in methods the account has (Settings › Account).
func (q *Queries) UserProviders(ctx context.Context, userID uuid.UUID) ([]string, error) {
	rows, err := q.db.Query(ctx, userProviders, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var provider string
		if err := rows.Scan(&provider); err != nil {
			return nil, err
		}
		items = append(items, provider)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

